def find_inversions(arr):
    n = len(arr)
    inversions = []
    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x)
                x = arr[x] - 1

            if len(cycle) > 1:
